7	function sign(action, method, payload) {
8	  method = method || 'GET';
9	  payload = payload || '';
10	  const region = 'cn-beijing', service = 'ark', host = 'open.volcengineapi.com';
11	  const version = '2024-01-01';
12	  const qs = `Action=${action}&Version=${version}`;
13	  const sha256 = s => crypto.createHash('sha256').update(s).digest('hex');
14	  const hmac = (k, s) => crypto.createHmac('sha256', k).update(s).digest();
15	  const now = new Date();
16	  const xDate = now.toISOString().replace(/[:-]/g, '').split('.')[0] + 'Z';
17	  const d = now.toISOString().split('T')[0].replace(/-/g, '');
18	  const hp = sha256(payload);
19	  const hd = { 'host': host, 'x-date': xDate, 'x-content-sha256': hp };
20	
21	  if (method === 'POST') hd['content-type'] = 'application/json';
22	
23	  const sh = Object.keys(hd).sort().join(';');
24	  const ch = Object.keys(hd).sort().map(k => k.toLowerCase() + ':' + hd[k].trim() + '\n').join('');
25	  const cr = [method, '/', qs, ch, sh, hp].join('\n');
26	  const hcr = sha256(cr);
27	  const cs = d + '/' + region + '/' + service + '/request';
28	  const sts = ['HMAC-SHA256', xDate, cs, hcr].join('\n');
29	  const kd = hmac(SK, d), kr = hmac(kd, region), ks = hmac(kr, service), ksg = hmac(ks, 'request');
30	  const sig = hmac(ksg, sts).toString('hex');
31	  const auth = `HMAC-SHA256 Credential=${AK}/${cs}, SignedHeaders=${sh}, Signature=${sig}`;
32	  return {
33	    url: 'https://' + host + '/?' + qs,
34	    headers: { 'Authorization': auth, 'X-Date': xDate, 'X-Content-Sha256': hp, 'Content-Type': 'application/json' },
35	    body: payload
36	  };
37	}
