47	      const req = https.request(opts, res => { let d = ''; res.on('data', c => d += c); res.on('end', () => r({ s: res.statusCode, b: d })); });
48	      req.on('error', e => r({ s: 0, b: e.message }));
49	      if (body) req.write(body);
50	      req.end();
51	    } else {
52	      https.get(opts, res => { let d = ''; res.on('data', c => d += c); res.on('end', () => r({ s: res.statusCode, b: d })); })
53	        .on('error', e => r({ s: 0, b: e.message }));
