291	      // Bridge for getting file details (ctime, tags) with pagination
292	      (window as any).__IFTO_getFilesDetail = async (folder: string, start: number, count: number): Promise<{files: any[], total: number}> => {
293	        try {
294	          const adapter = this.app.vault.adapter;
295	          if (!await adapter.exists(folder)) return { files: [], total: 0 };
296	          const result = await adapter.list(folder);
297	          const prefix = folder.endsWith('/') ? folder : folder + '/';
298	          const files = (result.files || [])
299	            .filter((f: string) => f.startsWith(prefix) && !f.substring(prefix.length).includes('/'))
300	            .map((f: string) => f.substring(prefix.length))
301	            .sort().reverse();
302	          const pageFiles = files.slice(start, start + count);
303	          const details: any[] = [];
304	          for (const f of pageFiles) {
305	            try {
306	              const fp = folder + '/' + f;
307	              const stat = await adapter.stat(fp);
308	              const content = await adapter.read(fp);
309	              const tags: string[] = [];
310	              const fm = content.match(/^---\n([\s\S]*?)\n---/);
311	              if (fm) {
312	                // Parse tags supporting three YAML shapes:
313	                //   1) tags: [a, b, c]              (inline array)
314	                //   2) tags: a                       (single scalar)
315	                //   3) tags:                         (multi-line list)
316	                //        - a
317	                //        - b
318	                const fmLines = fm[1].split(/\r?\n/);
319	                for (let li = 0; li < fmLines.length; li++) {
320	                  const lineMatch = fmLines[li].match(/^tags\s*:\s*(.*)$/);
321	                  if (!lineMatch) continue;
322	                  const rest = lineMatch[1].trim();
323	                  const inlineArr = rest.match(/^\[([^\]]*)\]$/);
324	                  if (inlineArr) {
325	                    tags.push(...inlineArr[1].split(/[,，]/).map(t => t.trim().replace(/^['"]|['"]$/g, '')).filter(t => t));
326	                  } else if (rest) {
327	                    tags.push(rest.replace(/^['"]|['"]$/g, ''));
328	                  } else {
329	                    for (let lj = li + 1; lj < fmLines.length; lj++) {
330	                      const item = fmLines[lj].match(/^\s+-\s+(.+)$/);
331	                      if (!item) break;
332	                      const v = item[1].trim().replace(/^['"]|['"]$/g, '');
333	                      if (v) tags.push(v);
334	                    }
335	                  }
336	                  break;
337	                }
338	              }
339	              details.push({ name: f, ctime: stat.ctime, tags });
340	            } catch (e) {
341	              details.push({ name: f, ctime: null, tags: [] });
342	            }
343	          }
344	          return { files: details, total: files.length };
345	        } catch (e) {
346	          console.error('IFTO: getFilesDetail error', e);
347	          return { files: [], total: 0 };
348	        }
349	      };
