394	      // Helper: convert ArrayBuffer/Buffer to base64 data URL
395	      const _bufToDataUrl = (path: string, buf: ArrayBuffer | Buffer): string => {
396	        const ext = (path.split('?')[0].split('.').pop() || 'png').toLowerCase();
397	        const bytes = new Uint8Array(buf as any);
398	        let binary = '';
399	        for (let i = 0; i < bytes.length; i++) {
400	          binary += String.fromCharCode(bytes[i]);
401	        }
402	        const mime: Record<string,string> = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', gif: 'image/gif', webp: 'image/webp', bmp: 'image/bmp', svg: 'image/svg+xml' };
403	        return `data:${mime[ext] || 'image/png'};base64,${btoa(binary)}`;
404	      };
