406	      // Bridge for resolving an image URL (supports vault paths and external URLs)
407	      (window as any).__IFTO_resolveImageUrl = async (path: string): Promise<string> => {
408	        if (!path) return '';
409	        try {
410	          // HTTP(S) URL — fetch via requestUrl to bypass CSP
411	          if (path.startsWith('http://') || path.startsWith('https://')) {
412	            try {
413	              const resp = await requestUrl({ url: path });
414	              if (resp && resp.arrayBuffer) {
415	                return _bufToDataUrl(path, resp.arrayBuffer);
416	              }
417	            } catch (e) {
418	              console.warn('IFTO: requestUrl failed, trying https fallback', e);
419	            }
420	            // Fallback: fetch via Node.js https/http module
421	            try {
422	              const mod = path.startsWith('https') ? require('https') : require('http');
423	              const buf = await new Promise<Buffer>((resolve, reject) => {
424	                mod.get(path, (res: any) => {
425	                  const chunks: Buffer[] = [];
426	                  res.on('data', (c: Buffer) => chunks.push(c));
427	                  res.on('end', () => resolve(Buffer.concat(chunks)));
428	                  res.on('error', reject);
429	                }).on('error', reject);
430	              });
431	              return _bufToDataUrl(path, buf);
432	            } catch (e2) {
433	              console.error('IFTO: https fallback also failed', e2);
434	            }
435	            return '';
436	          }
437	          // Vault path — read file binary
438	          const file = findFile(path);
439	          if (!file) return '';
440	          const arrayBuffer = await this.app.vault.readBinary(file);
441	          return _bufToDataUrl(path, arrayBuffer);
442	        } catch (e) {
443	          console.error('IFTO: resolve image url error', e);
444	        }
445	        return '';
446	      };
