761	      (window as any).__IFTO_getFilesFrontmatterRecursive = async (folder: string): Promise<{name: string, fm: Record<string,string>}[]> => {
762	        const recList = async (base: string, dir: string): Promise<{name: string, fm: Record<string,string>}[]> => {
763	          try {
764	            const adapter = this.app.vault.adapter;
765	            const result = await adapter.list(dir);
766	            const out: {name: string, fm: Record<string,string>}[] = [];
767	            for (const f of (result.files || [])) {
768	              if (!f.endsWith('.md')) continue;
769	              const content = await adapter.read(f);
770	              const fm: Record<string,string> = {};
771	              const m = content.match(/^---\n([\s\S]*?)\n---/);
772	              if (m) {
773	                m[1].split('\n').forEach(line => {
774	                  const kv = line.match(/^\s*([^:]+?)\s*:\s*(.+)/);
775	                  if (kv) fm[kv[1].trim()] = kv[2].trim().replace(/^['"]|['"]$/g, '');
776	                });
777	              }
778	              // Fallback: parse blockquote metadata (> **key:** value) if no YAML frontmatter
779	              if (!m) {
780	                const bqRegex = /> \*\*([^*]+)\*\*:\s*(.+)/g;
781	                let match: RegExpExecArray | null;
782	                while ((match = bqRegex.exec(content)) !== null) {
783	                  const key = match[1].trim();
784	                  const val = match[2].trim().replace(/^['"]|['"]$/g, '');
785	                  if (key && val) fm[key] = val;
786	                }
787	              }
788	              out.push({ name: f.substring(base.length + 1), fm });
789	            }
790	            for (const sub of (result.folders || [])) {
791	              const subOut = await recList(base, sub);
792	              out.push(...subOut);
793	            }
794	            return out;
795	          } catch (e) { return []; }
796	        };
797	        try {
798	          if (!await this.app.vault.adapter.exists(folder)) return [];
799	          return await recList(folder, folder);
800	        } catch (e) { console.error('IFTO: getFilesFrontmatterRecursive error', e); return []; }
