977	      // Helper: recursive search
978	      const _searchItem = async (adapter: any, dir: string, name: string, depth: number, maxDepth: number): Promise<{path: string, isFolder: boolean} | null> => {
979	        if (depth > maxDepth) return null;
980	        try {
981	          const result = await adapter.list(dir);
982	          // Check folders
983	          for (const folder of (result.folders || [])) {
984	            const folderName = folder.split('/').pop();
985	            if (folderName === name) return { path: folder, isFolder: true };
986	            // Recurse into subfolder
987	            const sub = await _searchItem(adapter, folder, name, depth + 1, maxDepth);
988	            if (sub) return sub;
989	          }
990	          // Check files
991	          for (const file of (result.files || [])) {
992	            if (!file.endsWith('.md')) continue;
993	            const fileName = file.split('/').pop();
994	            if (fileName === name) return { path: file, isFolder: false };
995	          }
996	          return null;
997	        } catch (e) { return null; }
