1072	  private async createCollectionNote() {
1073	    const folder = this.plugin.settings.inboxFolder || '010-信箱 INBOX/020-收集';
1074	    const templatePath = this.plugin.settings.collectionTemplate;
1075	    let content = '';
1076	    const now = new Date();
1077	    const ts = `${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}_${String(now.getHours()).padStart(2,'0')}${String(now.getMinutes()).padStart(2,'0')}${String(now.getSeconds()).padStart(2,'0')}`;
1078	    if (templatePath) {
1079	      try {
1080	        content = await this.app.vault.adapter.read(templatePath);
1081	      } catch (e) {
1082	        // Try appending .md if initial read fails
1083	        try {
1084	          content = await this.app.vault.adapter.read(templatePath + '.md');
1085	        } catch (e2) {
1086	          console.error('IFTO: template read failed', e, e2);
1087	          new Notice(`模板读取失败，请检查路径: ${templatePath}`);
1088	        }
1089	      }
1090	      // Process template variables
1091	      if (content) {
1092	        content = this.processTemplateVars(content, ts);
1093	      }
1094	    }
1095	    const fileName = `${ts}.md`;
1096	    const fullPath = `${folder}/${fileName}`;
1097	    try {
1098	      const exists = await this.app.vault.adapter.exists(folder);
1099	      if (!exists) await this.app.vault.createFolder(folder);
1100	      const file = await this.app.vault.create(fullPath, content);
1101	      new Notice(`已创建: ${fileName}`);
1102	      // Open in new tab with explicit editor focus
1103	      const leaf = this.app.workspace.getLeaf(true);
1104	      await leaf.openFile(file);
1105	      this.app.workspace.setActiveLeaf(leaf, false, true);
1106	      // Delayed focus — the editor's contenteditable may not be fully rendered yet
1107	      setTimeout(() => {
1108	        try {
1109	          const view = leaf.view as any;
1110	          if (view && view.editor && typeof view.editor.focus === 'function') {
1111	            view.editor.focus();
1112	          }
1113	        } catch (e) { /* ignore */ }
1114	      }, 60);
1115	    } catch (e) {
1116	      new Notice(`创建失败: ${e.message}`);
1117	    }
1118	  }
