1120	  private processTemplateVars(text: string, fileTitle?: string): string {
1121	    const now = new Date();
1122	    const y = now.getFullYear();
1123	    const M = now.getMonth() + 1;
1124	    const d = now.getDate();
1125	    const h = now.getHours();
1126	    const m = now.getMinutes();
1127	    const s = now.getSeconds();
1128	
1129	    // Replace {{date:format}} (e.g. {{date:YYYY年MM月DD日}})
1130	    text = text.replace(/\{\{date:([^}]+)\}\}/g, (_, fmt: string) => {
1131	      return fmt
1132	        .replace(/YYYY/g, String(y))
1133	        .replace(/YY/g, String(y).slice(-2))
1134	        .replace(/MM/g, String(M).padStart(2, '0'))
1135	        .replace(/M/g, String(M))
1136	        .replace(/DD/g, String(d).padStart(2, '0'))
1137	        .replace(/D/g, String(d));
1138	    });
1139	
1140	    // Replace {{time:format}} (e.g. {{time:HH:mm:ss}})
1141	    text = text.replace(/\{\{time:([^}]+)\}\}/g, (_, fmt: string) => {
1142	      return fmt
1143	        .replace(/HH/g, String(h).padStart(2, '0'))
1144	        .replace(/H/g, String(h))
1145	        .replace(/hh/g, String(h % 12 || 12).padStart(2, '0'))
1146	        .replace(/h/g, String(h % 12 || 12))
1147	        .replace(/mm/g, String(m).padStart(2, '0'))
1148	        .replace(/ss/g, String(s).padStart(2, '0'))
1149	        .replace(/A/g, h < 12 ? 'AM' : 'PM');
1150	    });
1151	
1152	    // Replace {{date}} with YYYY-MM-DD
1153	    text = text.replace(/\{\{date\}\}/g, `${y}-${String(M).padStart(2, '0')}-${String(d).padStart(2, '0')}`);
1154	
1155	    // Replace {{time}} with HH:mm
1156	    text = text.replace(/\{\{time\}\}/g, `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`);
1157	
1158	    // Handle Templater-style tags
1159	    // <% tp.file.creation_date() %> or <% tp.file.creation_date("YYYY-MM-DD") %>
1160	    text = text.replace(/<%\s*tp\.file\.creation_date\s*\(\s*(?:"([^"]*)"|'([^']*)')?\s*\)\s*%>/g, (_, fmt1?: string, fmt2?: string) => {
1161	      const fmt = (fmt1 || fmt2 || 'YYYY-MM-DD').replace(/HH/, String(h).padStart(2,'0')).replace(/mm/, String(m).padStart(2,'0')).replace(/ss/, String(s).padStart(2,'0'));
1162	      return fmt.replace(/YYYY/g, String(y)).replace(/YY/g, String(y).slice(-2)).replace(/MM/g, String(M).padStart(2,'0')).replace(/M/g, String(M)).replace(/DD/g, String(d).padStart(2,'0')).replace(/D/g, String(d));
1163	    });
1164	    // <% tp.date.now() %> or <% tp.date.now("YYYY-MM-DD") %>
1165	    text = text.replace(/<%\s*tp\.date\.now\s*\(\s*(?:"([^"]*)"|'([^']*)')?\s*\)\s*%>/g, (_, fmt1?: string, fmt2?: string) => {
1166	      const fmt = (fmt1 || fmt2 || 'YYYY-MM-DD').replace(/HH/, String(h).padStart(2,'0')).replace(/mm/, String(m).padStart(2,'0')).replace(/ss/, String(s).padStart(2,'0'));
1167	      return fmt.replace(/YYYY/g, String(y)).replace(/YY/g, String(y).slice(-2)).replace(/MM/g, String(M).padStart(2,'0')).replace(/M/g, String(M)).replace(/DD/g, String(d).padStart(2,'0')).replace(/D/g, String(d));
1168	    });
1169	    // <% tp.date.now("format", offset) %> with day offset
1170	    text = text.replace(/<%\s*tp\.date\.now\s*\(\s*(?:"([^"]*)"|'([^']*)')\s*,\s*(-?\d+)\s*\)\s*%>/g, (_, fmt1: string, fmt2: string, offset: string) => {
1171	      const fmt = (fmt1 || fmt2 || 'YYYY-MM-DD').replace(/HH/, String(h).padStart(2,'0')).replace(/mm/, String(m).padStart(2,'0')).replace(/ss/, String(s).padStart(2,'0'));
1172	      const od = new Date(now.getTime() + parseInt(offset) * 86400000);
1173	      const oy = od.getFullYear(), oM = od.getMonth()+1, oDate = od.getDate();
1174	      return fmt.replace(/YYYY/g, String(oy)).replace(/YY/g, String(oy).slice(-2)).replace(/MM/g, String(oM).padStart(2,'0')).replace(/M/g, String(oM)).replace(/DD/g, String(oDate).padStart(2,'0')).replace(/D/g, String(oDate));
1175	    });
1176	    // <% tp.file.title %> → replace with actual file title (timestamp)
1177	    text = text.replace(/<%\s*tp\.file\.title\s*\(\s*\)\s*%>/g, fileTitle || '');
1178	    // <% tp.file.folder %> → replace with empty
1179	    text = text.replace(/<%\s*tp\.file\.folder\s*\(\s*\)\s*%>/g, '');
1180	
1181	    return text;
1182	  }
1183	}
