1234	  async loadSettings() {
1235	    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
1236	    // Normalize widgetOrder: append any known widget ids missing from saved order,
1237	    // so newly-added widgets (e.g. todotoday) become reorderable in the settings UI
1238	    // instead of being silently appended only at render time.
1239	    const known = DEFAULT_SETTINGS.widgetOrder.split(',').map(s => s.trim()).filter(s => s);
1240	    const cur = (this.settings.widgetOrder || '').split(',').map(s => s.trim()).filter(s => s);
1241	    let changed = false;
1242	    known.forEach(id => { if (cur.indexOf(id) === -1) { cur.push(id); changed = true; } });
1243	    if (changed) {
1244	      this.settings.widgetOrder = cur.join(',');
1245	      await this.saveSettings();
1246	    }
1247	  }
