1253	  async activateView() {
1254	    const { workspace } = this.app;
1255	    const existing = workspace.getLeavesOfType(IFTO_VIEW_TYPE);
1256	    if (existing.length > 0) {
1257	      workspace.revealLeaf(existing[0]);
1258	      return;
1259	    }
1260	    const leaf = workspace.getLeaf(true);
1261	    await leaf.setViewState({ type: IFTO_VIEW_TYPE, active: true });
1262	    workspace.revealLeaf(leaf);
1263	  }
